        ItemStack itemInOffHand = utilityComponent != null ? utilityComponent.getActiveItem() : null;
        Item primaryItem = itemInHand == null || itemInHand.isEmpty() ? null : itemInHand.getItem();
        Item item = secondaryItem = itemInOffHand == null || itemInOffHand.isEmpty() ? null : itemInOffHand.getItem();
        Item item2 = mouseButtonType == MouseButtonType.Left ? primaryItem : (mouseButtonType == MouseButtonType.Right && secondaryItem != null ? secondaryItem : primaryItem);
        WorldInteraction worldInteraction_ = packet.worldInteraction;
        BlockPosition blockPositionPacket = worldInteraction_.blockPosition;
        if (!ref.isValid()) {
            return;
        }
        EntityStore entityComponentStore = componentAccessor.getExternalData();
        Vector3i targetBlock = blockPositionPacket == null ? null : new Vector3i(blockPositionPacket.x, blockPositionPacket.y, blockPositionPacket.z);
        Ref<EntityStore> targetRef = worldInteraction_.entityId < 0 ? null : entityComponentStore.getRefFromNetworkId(worldInteraction_.entityId);
