        if (transformComponent == null) {
            return false;
        }
        float maxDistanceSq = InteractionValidation.getPlayerInteractionDistanceSq(ref, componentAccessor, heldItem);
        float eyeHeight = InteractionValidation.getEyeHeight(ref, componentAccessor);
