    public boolean testNeighboursForLocalLight(@Nonnull LocalCachedChunkAccessor accessor, @Nonnull WorldChunk worldChunk, int chunkX, int chunkY, int chunkZ) {
        Vector3ic[][] blockParts = Vector3iUtil.BLOCK_PARTS;
        for (int partType = 0; partType < this.fromSections.length; ++partType) {
            Object[] partSections = this.fromSections[partType];
            Arrays.fill(partSections, null);
            Vector3ic[] directions = blockParts[partType];
            for (int i = 0; i < directions.length; ++i) {
                Vector3ic side = directions[i];
                int nx = chunkX + side.x();
                int ny = chunkY + side.y();
                int nz = chunkZ + side.z();
                if (ny < 0 || ny >= 10) continue;
                if (nx == chunkX && nz == chunkZ) {
                    BlockSection fromSection = worldChunk.getBlockChunk().getSectionAtIndex(ny);
                    if (!fromSection.hasLocalLight()) {
                        return true;
                    }
                    partSections[i] = fromSection;
                    continue;
                }
                WorldChunk neighbourChunk = accessor.getChunkIfInMemory(nx, nz);
                if (neighbourChunk == null) {
                    return true;
                }
                BlockSection fromSection = neighbourChunk.getBlockChunk().getSectionAtIndex(ny);
                if (!fromSection.hasLocalLight()) {
                    return true;
                }
                partSections[i] = fromSection;
            }
        }
        return false;
    }

    public void propagateSides(@Nonnull BlockSection toSection, @Nonnull ChunkLightDataBuilder globalLight, @Nonnull BitSet bitSetQueue) {
        BlockSection[] fromSectionsSides = this.fromSections[0];
        int i = 0;
        this.propagateSide(bitSetQueue, fromSectionsSides[i++], toSection, globalLight, (a, b) -> ChunkUtil.indexBlock(a, 0, b), (a, b) -> ChunkUtil.indexBlock(a, 31, b));
        this.propagateSide(bitSetQueue, fromSectionsSides[i++], toSection, globalLight, (a, b) -> ChunkUtil.indexBlock(a, 31, b), (a, b) -> ChunkUtil.indexBlock(a, 0, b));
        this.propagateSide(bitSetQueue, fromSectionsSides[i++], toSection, globalLight, (a, b) -> ChunkUtil.indexBlock(a, b, 31), (a, b) -> ChunkUtil.indexBlock(a, b, 0));
        this.propagateSide(bitSetQueue, fromSectionsSides[i++], toSection, globalLight, (a, b) -> ChunkUtil.indexBlock(a, b, 0), (a, b) -> ChunkUtil.indexBlock(a, b, 31));
        this.propagateSide(bitSetQueue, fromSectionsSides[i++], toSection, globalLight, (a, b) -> ChunkUtil.indexBlock(31, a, b), (a, b) -> ChunkUtil.indexBlock(0, a, b));
        this.propagateSide(bitSetQueue, fromSectionsSides[i++], toSection, globalLight, (a, b) -> ChunkUtil.indexBlock(0, a, b), (a, b) -> ChunkUtil.indexBlock(31, a, b));
    }

    private void propagateSide(@Nonnull BitSet bitSetQueue, @Nullable BlockSection fromSection, @Nonnull BlockSection toSection, @Nonnull ChunkLightDataBuilder toLight, @Nonnull IntBinaryOperator fromIndex, @Nonnull IntBinaryOperator toIndex) {
        if (fromSection == null) {
            return;
        }
        ChunkLightData fromLight = fromSection.getLocalLight();
        for (int a = 0; a < 32; ++a) {
            for (int b = 0; b < 32; ++b) {
                int fromBlockIndex = fromIndex.applyAsInt(a, b);
                int toBlockIndex = toIndex.applyAsInt(a, b);
                BlockType fromBlockType = BlockType.getAssetMap().getAsset(fromSection.get(fromBlockIndex));
                Opacity fromOpacity = fromBlockType.getOpacity();
                if (fromOpacity == Opacity.Solid) continue;
                short lightValue = fromLight.getLightRaw(fromBlockIndex);
                byte redLight = ChunkLightData.getLightValue(lightValue, 0);
                byte greenLight = ChunkLightData.getLightValue(lightValue, 1);
                byte blueLight = ChunkLightData.getLightValue(lightValue, 2);
                byte skyLight = ChunkLightData.getLightValue(lightValue, 3);
                if (redLight < 2 && greenLight < 2 && blueLight < 2 && skyLight < 2) continue;
                byte propagatedRedValue = (byte)(redLight - 1);
                byte propagatedGreenValue = (byte)(greenLight - 1);
                byte propagatedBlueValue = (byte)(blueLight - 1);
                byte propagatedSkyValue = (byte)(skyLight - 1);
                if (fromOpacity == Opacity.Semitransparent || fromOpacity == Opacity.Cutout) {
                    propagatedRedValue = (byte)(propagatedRedValue - 1);
                    propagatedGreenValue = (byte)(propagatedGreenValue - 1);
                    propagatedBlueValue = (byte)(propagatedBlueValue - 1);
                    propagatedSkyValue = (byte)(propagatedSkyValue - 1);
                }
                if (propagatedRedValue < 1 && propagatedGreenValue < 1 && propagatedBlueValue < 1 && propagatedSkyValue < 1) continue;
                this.propagateLight(bitSetQueue, propagatedRedValue, propagatedGreenValue, propagatedBlueValue, propagatedSkyValue, toSection, toLight, toBlockIndex);
            }
        }
    }

