        if (name.equalsIgnoreCase(HytaleServer.get().getConfig().getDefaults().getWorld())) {
            sender.sendMessage(MESSAGE_UNIVERSE_REMOVE_WORLD_CHANGE_DEFAULT_WORLD);
            return;
        }
