    public void handleClientPlaceBlock(@Nonnull ClientPlaceBlock packet, @Nonnull PlayerRef playerRef, @Nonnull Ref<EntityStore> ref, @Nonnull World world, @Nonnull Store<EntityStore> store) {
        Player playerComponent = store.getComponent(ref, Player.getComponentType());
        assert (playerComponent != null);
        InventoryComponent.Hotbar hotbarComponent = store.getComponent(ref, InventoryComponent.Hotbar.getComponentType());
        if (hotbarComponent == null) {
            return;
        }
        Vector3i targetBlock = new Vector3i(packet.position.x, packet.position.y, packet.position.z);
        BlockRotation blockRotation = new BlockRotation(packet.rotation.rotationYaw, packet.rotation.rotationPitch, packet.rotation.rotationRoll);
        TransformComponent transformComponent = store.getComponent(ref, TransformComponent.getComponentType());
        Store<ChunkStore> chunkStore = world.getChunkStore().getStore();
        long chunkIndex = ChunkUtil.indexChunkFromBlock(targetBlock.x, targetBlock.z);
        Ref<ChunkStore> chunkReference = chunkStore.getExternalData().getChunkReference(chunkIndex);
        if (chunkReference == null) {
            return;
        }
        BlockChunk blockChunk = chunkStore.getComponent(chunkReference, BlockChunk.getComponentType());
        if (blockChunk == null) {
            return;
        }
        BlockSection section = blockChunk.getSectionAtBlockY(targetBlock.y);
        if (section == null) {
            return;
        }
        ItemStack itemInHand = InventoryComponent.getItemInHand(store, ref);
        if (itemInHand == null && !packet.quickReplace) {
            section.invalidateBlock(targetBlock.x, targetBlock.y, targetBlock.z);
            return;
        }
        if (!InteractionValidation.canPlayerInteractWithBlock(ref, store, itemInHand, targetBlock)) {
            LOGGER.at(Level.WARNING).log("Entity %d failed place block packet distance check at [%d, %d, %d]", ref.getIndex(), targetBlock.x, targetBlock.y, targetBlock.z);
            section.invalidateBlock(targetBlock.x, targetBlock.y, targetBlock.z);
            return;
        }
        String heldBlockKey = itemInHand.getBlockKey();
        if (heldBlockKey == null && !packet.quickReplace) {
            section.invalidateBlock(targetBlock.x, targetBlock.y, targetBlock.z);
            return;
        }
        if (packet.placedBlockId != -1) {
            String clientPlacedBlockTypeKey = BlockType.getAssetMap().getAsset(packet.placedBlockId).getId();
            BlockType heldBlockType = (BlockType)BlockType.getAssetMap().getAsset(heldBlockKey);
            if (packet.quickReplace || packet.quickRetype || packet.noPhysics || heldBlockType != null && BlockPlaceUtils.canPlaceBlock(heldBlockType, clientPlacedBlockTypeKey)) {
                heldBlockKey = clientPlacedBlockTypeKey;
            }
        }
        BlockPlaceUtils.placeBlock(ref, itemInHand, heldBlockKey, hotbarComponent.getInventory(), new Vector3i(), targetBlock, blockRotation, hotbarComponent.getActiveSlot(), playerComponent.getGameMode() != GameMode.Creative, chunkReference, chunkStore, store, packet.quickReplace, packet.quickRetype, packet.noPhysics);
    }

