        HytaleLogManager.resetFinally();
        Sentry.endSession();
        SCHEDULED_EXECUTOR.schedule(() -> {
            LOGGER.at(Level.SEVERE).log("Forcing shutdown!");
            Runtime.getRuntime().halt(reason.getExitCode());
        }, 3L, TimeUnit.SECONDS);
