        return "BlockType{id=" + this.id + ", unknown=" + this.unknown + ", group='" + this.group + "', blockSoundSetId='" + this.blockSoundSetId + "', blockSoundSetIndex=" + this.blockSoundSetIndex + ", particles=" + Arrays.toString(this.particles) + ", blockParticleSetId='" + this.blockParticleSetId + "', blockBreakingDecalId='" + this.blockBreakingDecalId + "', particleColor=" + String.valueOf(this.particleColor) + ", textureComputedColor=" + String.valueOf(this.textureComputedColor) + ", effect=" + Arrays.toString((Object[])this.effect) + ", textures=" + Arrays.toString(this.textures) + ", textureSideMask='" + this.textureSideMask + "', cubeShadingMode=" + String.valueOf((Object)this.cubeShadingMode) + ", customModel='" + this.customModel + "', customModelTexture=" + Arrays.toString(this.customModelTexture) + ", customModelScale=" + this.customModelScale + ", customModelAnimation='" + this.customModelAnimation + "', drawType=" + String.valueOf((Object)this.drawType) + ", material=" + String.valueOf((Object)this.material) + ", opacity=" + String.valueOf((Object)this.opacity) + ", requiresAlphaBlending=" + this.requiresAlphaBlending + ", tickProcedure" + String.valueOf(this.tickProcedure) + ", tintUp=" + Arrays.toString(this.tintUp) + ", tintDown=" + Arrays.toString(this.tintDown) + ", tintNorth=" + Arrays.toString(this.tintNorth) + ", tintSouth=" + Arrays.toString(this.tintSouth) + ", tintWest=" + Arrays.toString(this.tintWest) + ", tintEast=" + Arrays.toString(this.tintEast) + ", biomeTintUp=" + this.biomeTintUp + ", biomeTintDown=" + this.biomeTintDown + ", biomeTintNorth=" + this.biomeTintNorth + ", biomeTintSouth=" + this.biomeTintSouth + ", biomeTintWest=" + this.biomeTintWest + ", biomeTintEast=" + this.biomeTintEast + ", randomRotation=" + String.valueOf((Object)this.randomRotation) + ", variantRotation=" + String.valueOf(this.variantRotation) + ", flipType=" + String.valueOf((Object)this.flipType) + ", rotationYawPlacementOffset=" + String.valueOf(this.rotationYawPlacementOffset) + ", transitionTexture='" + this.transitionTexture + "', transitionToGroups=" + Arrays.toString(this.transitionToGroups) + ", hitboxType='" + this.hitboxType + "', hitboxTypeIndex=" + this.hitboxTypeIndex + ", interactionHitboxType='" + this.interactionHitboxType + "', interactionHitboxTypeIndex=" + this.interactionHitboxTypeIndex + ", light=" + String.valueOf(this.light) + ", movementSettings=" + String.valueOf(this.movementSettings) + ", flags=" + String.valueOf(this.flags) + ", interactionHint='" + this.interactionHint + "', isTrigger=" + this.isTrigger + ", damageToEntities=" + this.damageToEntities + ", allowsMultipleUsers=" + this.allowsMultipleUsers + ", bench=" + String.valueOf(this.bench) + ", gathering=" + String.valueOf(this.gathering) + ", placementSettings=" + String.valueOf(this.placementSettings) + ", state=" + String.valueOf(this.state) + ", ambientSoundEventId='" + this.ambientSoundEventId + "', ambientSoundEventIndex='" + this.ambientSoundEventIndex + "', conditionalSounds=" + Arrays.toString(this.conditionalSounds) + ", interactionSoundEventId='" + this.interactionSoundEventId + "', interactionSoundEventIndex='" + this.interactionSoundEventIndex + "', isLooping=" + this.isLooping + ", farming=" + String.valueOf(this.farming) + ", fallingBlockSettings=" + String.valueOf(this.fallingBlockSettings) + ", supportDropType=" + String.valueOf((Object)this.supportDropType) + ", maxSupportDistance=" + this.maxSupportDistance + ", support=" + String.valueOf(this.support) + ", supporting=" + String.valueOf(this.supporting) + ", interactions=" + String.valueOf(this.interactions) + ", railConfig=" + String.valueOf(this.railConfig) + "}";
