        Bench.CODEC.register((Object)BenchType.Processing, ProcessingBench.class, ProcessingBench.CODEC);
        Bench.CODEC.register((Object)BenchType.DiagramCrafting, DiagramCraftingBench.class, DiagramCraftingBench.CODEC);
